const CACHE = `learn-git-${VERSION}`;
const DEV_HOST = /^(localhost|127\.\d+\.\d+\.\d+|\[::1\])$/.test(self.location.hostname);

self.addEventListener('install', (event) => {
  // No skipWaiting here: the page shows an "Update available" toast and asks (SKIP_WAITING message),
  // so a new version never swaps in under someone in the middle of a lesson.
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    // cache: 'reload' bypasses the HTTP cache so a new version never precaches stale bytes.
    await Promise.all(PRECACHE.map((url) => cache.add(new Request(url, { cache: 'reload' }))));
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) if (key.startsWith('learn-git-') && key !== CACHE) await caches.delete(key);
    await self.clients.claim();
  })());
});

self.addEventListener('message', (event) => {
  if (event.data === 'SKIP_WAITING') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;                       // incl. the analytics POSTs (js/learnlog/send.js)
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;       // never touch cross-origin (Supabase REST + analytics, the jsdelivr SDK)
  if (url.pathname.startsWith('/__pg/')) return;         // gateway login/guest routes
  if (req.headers.has('range')) return;                  // video seeking: 206s cannot be cached
  // The OAuth return (/app?code=... or ?error=...) always goes to the network: it is never answered
  // from the cached shell and never stored, so a stale shell can't get in the way of signing in.
  if (url.searchParams.has('code') || url.searchParams.has('error') || url.searchParams.has('error_description')) return;
  // /admin is online-only and not part of the app: not precached, not cached at all.
  if (url.pathname === '/admin' || url.pathname.startsWith('/admin/') || url.pathname === '/admin.html') return;
  event.respondWith(handle(req, url));
});

async function handle(req, url) {
  const cache = await caches.open(CACHE);
  const isNav = req.mode === 'navigate';
  // Navigations are matched ignoring the query string (?nosw, ?utm...), and fall back to the app shell offline.
  const match = () => cache.match(req, { ignoreSearch: isNav });
  const fromNet = () => fetch(req).then((res) => {
    // Only whole, successful, basic responses are worth keeping.
    if (res.ok && res.status === 200 && res.type === 'basic') cache.put(req, res.clone());
    return res;
  });

  // On localhost, prefer the network so edits show up immediately; the cache is only the offline fallback.
  if (DEV_HOST) {
    try { return await fromNet(); } catch { return (await match()) || shellFallback(cache, isNav) || Response.error(); }
  }

  const cached = await match();
  if (cached) { fromNet().catch(() => {}); return cached; }   // stale-while-revalidate
  try { return await fromNet(); } catch { return (await shellFallback(cache, isNav)) || Response.error(); }
}

function shellFallback(cache, isNav) {
  return isNav ? cache.match('index.html') : undefined;
}

// ---- push reminders (supabase/functions/send-reminders, .notes/push-reminders.md) -----------------
// The payload is JSON { title, body, tag, url }. A push must always show a notification
// (userVisibleOnly), so a missing or broken payload still gets a generic one.
self.addEventListener('push', (event) => {
  let data = {};
  try { data = event.data ? event.data.json() : {}; } catch { data = { body: event.data?.text() || '' }; }
  event.waitUntil(self.registration.showNotification(data.title || 'Time for a quick lesson', {
    body: data.body || 'One three-minute lesson keeps your streak going.',
    icon: 'icons/icon-192.png',
    badge: 'icons/icon-192.png',
    tag: data.tag || 'streak',          // the local reminder in js/pwa.js uses the same tag: one replaces the other
    data: { url: data.url || 'app' },
  }));
});

// Tapping it focuses an open game tab (or the installed app), else opens the game.
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  event.waitUntil((async () => {
    const scope = self.registration.scope;
    // /app on Vercel; a plain static server (localhost) has no /app route, only index.html.
    const target = new URL(DEV_HOST ? 'index.html' : event.notification.data?.url || 'app', scope).href;
    const isGame = (c) => {
      const p = new URL(c.url).pathname;
      return c.url.startsWith(scope) && (p === '/app' || p.endsWith('/index.html')) && !p.startsWith('/admin') && !p.startsWith('/site/');
    };
    const wins = (await self.clients.matchAll({ type: 'window', includeUncontrolled: true })).filter(isGame);
    const open = wins.find((c) => c.focused) || wins[0];
    if (open) { try { return await open.focus(); } catch { /* focus not allowed: open a new window */ } }
    return self.clients.openWindow(target);
  })());
});
